import fs from 'node:fs';
import path from 'node:path';
import { ESS_USER_FILE } from './constants';

export interface EssUser {
  username: string;
  password: string;
  firstName: string;
  lastName: string;
  /** Employee number from the URL after creation (…/viewPersonalDetails/empNumber/<n>). */
  empNumber?: string;
}

// The user itself is generated by buildEssUser() in test-data/users.ts.

export function saveEssUser(user: EssUser) {
  fs.mkdirSync(path.dirname(ESS_USER_FILE), { recursive: true });
  fs.writeFileSync(ESS_USER_FILE, JSON.stringify(user, null, 2));
}

export function readEssUser(): EssUser {
  if (!fs.existsSync(ESS_USER_FILE)) {
    throw new Error('ESS user file not found. Run the "setup" project first (tests/auth.setup.ts).');
  }
  return JSON.parse(fs.readFileSync(ESS_USER_FILE, 'utf8')) as EssUser;
}
